begin;
do $$
declare tid uuid; admin_id uuid; eid uuid; fid uuid; rid uuid; sid uuid; child athletics_class_sessions; relay athletics_class_sessions; ids uuid[]; girl uuid; boy uuid; late uuid; h uuid; entry uuid; h2 uuid; e2 uuid; team uuid; score_before text; oldcount integer;
begin
 select id into tid from tournaments where slug='intercolour-athletics-2026';select user_id into admin_id from system_admins limit 1;
 select md5(coalesce(jsonb_agg(to_jsonb(x) order by to_jsonb(x)::text)::text,'')) into score_before from athletics_scoreboard_overall x;
 perform set_config('request.jwt.claim.sub',admin_id::text,true);execute 'set local role authenticated';
 select id into eid from athletics_events where tournament_id=tid and discipline='track' limit 1;
 select id into fid from athletics_events where tournament_id=tid and discipline='field' limit 1;
 select id into rid from athletics_events where tournament_id=tid and discipline='relay' limit 1;
 select id into girl from athletics_athletes where tournament_id=tid and active and gender='F' and level='Y7' limit 1;
 select id into boy from athletics_athletes where tournament_id=tid and active and gender='M' and level='Y8' limit 1;
 select id into late from athletics_athletes where tournament_id=tid and active and gender='F' and level='Y7' and id<>girl limit 1;
 ids:=array[girl,boy];
 insert into athletics_class_sessions(tournament_id,template_event_id,title,session_date,category,categories,gender,timing_method) values(tid,eid,'ROLLBACK v3',current_date,'All',array['Y7','Y8'],'All','manual') returning id into sid;
 perform athletics_save_class_attendance(sid,ids);
 select * into child from athletics_add_class_activity(sid,fid,'All','Dry','not_applicable',3);
 if child.attendance_recorded or exists(select 1 from athletics_class_attendance where session_id=child.id) then raise exception 'New activity copied attendance';end if;
 begin perform athletics_save_class_marks(child.id,1,jsonb_build_array(jsonb_build_object('athlete_id',girl,'mark',4.5,'status','valid')));raise exception 'New activity bypassed attendance';exception when insufficient_privilege then null;end;
 perform athletics_save_class_attendance(child.id,array[girl]);
 if (select count(*) from athletics_class_attendance where session_id=sid and available)<>2 then raise exception 'Child attendance changed parent';end if;
 perform athletics_save_class_marks(child.id,1,jsonb_build_array(jsonb_build_object('athlete_id',girl,'mark',4.5,'status','valid')));
 perform athletics_save_class_marks(child.id,1,jsonb_build_array(jsonb_build_object('athlete_id',girl,'mark',4.6,'status','valid')));
 if (select count(*) from athletics_class_mark_audit where session_id=child.id)<>1 then raise exception 'Correction audit missing';end if;
 if not exists(select 1 from athletics_class_mark_audit where session_id=child.id and (before_value->>'mark')::numeric=4.5 and (after_value->>'mark')::numeric=4.6 and changed_by=admin_id) then raise exception 'Incorrect audit values';end if;
 begin update athletics_class_mark_audit set actor_label='changed' where session_id=child.id;raise exception 'Audit editable';exception when insufficient_privilege then null;end;
 update athletics_class_sessions set implement_kg=4 where id=child.id;
 perform athletics_save_class_marks(child.id,1,jsonb_build_array(jsonb_build_object('athlete_id',girl,'mark',4.7,'status','valid')));
 if (select implement_kg from athletics_class_marks where session_id=child.id and attempt_no=1)<>3 then raise exception 'Correction lost original implement';end if;
 perform athletics_save_class_marks(child.id,2,jsonb_build_array(jsonb_build_object('athlete_id',girl,'mark',4.2,'status','valid')));
 if (select implement_kg from athletics_class_marks where session_id=child.id and attempt_no=2)<>4 then raise exception 'New mark missed new default';end if;
 perform athletics_generate_class_heats(sid,'mixed',1,0,ids);
 select id into h from athletics_class_heats where session_id=sid and heat_number=1;
 select id into h2 from athletics_class_heats where session_id=sid and heat_number=2;
 select id into entry from athletics_class_heat_entries where heat_id=h;
 select id into e2 from athletics_class_heat_entries where heat_id=h2;
 perform athletics_edit_class_series(sid,1,jsonb_build_array(jsonb_build_object('id',entry,'heat_id',h2,'lane',1),jsonb_build_object('id',e2,'heat_id',h,'lane',1)));
 if (select heat_id from athletics_class_heat_entries where id=entry)<>h2 then raise exception 'Series swap failed';end if;
 perform athletics_save_class_heat(h2,jsonb_build_array(jsonb_build_object('id',entry,'official_time',12.345,'status','finished','timing_method','photo_finish')),true);
 if not exists(select 1 from athletics_class_marks where session_id=sid and timing_method='photo_finish') then raise exception 'Photo method not stored';end if;
 begin perform athletics_edit_class_series(sid,1,jsonb_build_array(jsonb_build_object('id',entry,'heat_id',h2,'lane',2)));raise exception 'Recorded heat moved';exception when raise_exception then if sqlerrm<>'A series with saved results cannot be rearranged' then raise;end if;end;
 -- One repeater only. Later attendance edits stay scoped to their own activity.
 perform athletics_generate_class_heats(sid,'mixed',8,0,array[girl]);
 if (select count(*) from athletics_class_heat_entries where session_id=sid and round_no=2)<>1 then raise exception 'Unselected runner repeated';end if;
 perform athletics_save_class_attendance(child.id,array[boy,late]);
 if not exists(select 1 from athletics_class_attendance where session_id=child.id and athlete_id=girl and present and not available) then raise exception 'Attendance history lost';end if;
 if not exists(select 1 from athletics_class_attendance where session_id=sid and athlete_id=girl and available) then raise exception 'Child departure changed track attendance';end if;
 if exists(select 1 from athletics_class_attendance where session_id=sid and athlete_id=late and available) then raise exception 'Child arrival changed track attendance';end if;
 perform athletics_save_class_attendance(sid,array[boy,late]);
 if not exists(select 1 from athletics_class_attendance where session_id=child.id and athlete_id=late and present and available) then raise exception 'Late arrival missing';end if;
 if (select count(*) from athletics_class_marks where session_id=child.id)<>2 then raise exception 'Departing deleted marks';end if;
 begin perform athletics_generate_class_heats(sid,'mixed',8,0,array[girl]);raise exception 'Departed runner selected';exception when raise_exception then if sqlerrm<>'Select available participants for this round' then raise;end if;end;
 perform athletics_generate_class_heats(sid,'gender',8,0,null);
 if exists(select 1 from athletics_class_heat_entries where session_id=sid and round_no=3 and athlete_id=girl) then raise exception 'Departed runner generated';end if;
 perform athletics_save_class_attendance(sid,array[girl,boy,late]);
 select * into relay from athletics_add_class_activity(sid,rid,'F','','manual',null);
 if relay.attendance_recorded or exists(select 1 from athletics_class_attendance where session_id=relay.id) then raise exception 'Relay copied attendance';end if;
 begin perform athletics_save_class_attendance(relay.id,array[boy]);raise exception 'Male accepted in female relay attendance';exception when raise_exception then if sqlerrm<>'An athlete does not belong to the selected categories / gender' then raise;end if;end;
 perform athletics_save_class_attendance(relay.id,array[girl,late]);
 perform athletics_configure_class_relay(relay.id,1,jsonb_build_array(jsonb_build_object('name','Custom team','athletes',array[late,girl])));
 select id into team from athletics_class_relay_teams where session_id=relay.id;
 if not exists(select 1 from athletics_class_relay_legs where team_id=team and athlete_id=late and leg_order=1) then raise exception 'Relay order wrong';end if;
 perform athletics_save_class_relay(team,60.123,'valid','manual');
 if (select count(*) from athletics_class_marks where session_id=relay.id and mark=60.123)<>2 then raise exception 'Team marks missing';end if;
 begin perform athletics_configure_class_relay(relay.id,1,jsonb_build_array(jsonb_build_object('name','Replacement','athletes',array[girl])));raise exception 'Recorded relay changed';exception when raise_exception then if sqlerrm<>'Relay membership is locked after results; create a new attempt' then raise;end if;end;
 begin perform athletics_configure_class_relay(relay.id,2,jsonb_build_array(jsonb_build_object('name','Wrong gender','athletes',array[boy])));raise exception 'Wrong relay gender allowed';exception when insufficient_privilege then null;end;
 if exists(select 1 from athletics_class_relay_teams where session_id=relay.id and attempt_no=2) then raise exception 'Partial team saved on failure';end if;
 perform athletics_configure_class_relay(relay.id,2,jsonb_build_array(jsonb_build_object('name','New order','athletes',array[girl,late])));
 update athletics_class_sessions set closed_at=now() where id=sid;
 begin perform athletics_save_class_marks(child.id,3,jsonb_build_array(jsonb_build_object('athlete_id',girl,'mark',5,'status','valid')));raise exception 'Closed session writable';exception when raise_exception then if sqlerrm<>'Session closed. Reopen it before making changes.' then raise;end if;end;
 begin perform athletics_save_class_attendance(sid,array[girl]);raise exception 'Closed attendance writable';exception when raise_exception then if sqlerrm<>'Session closed. Reopen it before making changes.' then raise;end if;end;
 update athletics_class_sessions set closed_at=null where id=sid;
 perform athletics_save_class_marks(child.id,3,jsonb_build_array(jsonb_build_object('athlete_id',girl,'mark',5,'status','valid')));
 if (select count(distinct conditions) from athletics_craighouse_history where source_label='ROLLBACK v3' and athlete_id=girl and discipline='field')<>2 then raise exception 'Implement comparisons mixed';end if;
 perform set_config('request.jwt.claim.sub','00000000-0000-0000-0000-000000000001',true);
 if exists(select 1 from athletics_class_mark_audit) or exists(select 1 from athletics_class_relay_teams) or exists(select 1 from athletics_class_relay_legs) then raise exception 'Unauthorized read';end if;
 begin perform athletics_class_lock(sid);raise exception 'Unauthorized RPC';exception when raise_exception then if sqlerrm<>'Not authorized' then raise;end if;end;
 execute 'set local role postgres';
 if score_before is distinct from (select md5(coalesce(jsonb_agg(to_jsonb(x) order by to_jsonb(x)::text)::text,'')) from athletics_scoreboard_overall x) then raise exception 'Official points modified';end if;
end $$;
rollback;
select 'PASS v3: multi-event independent attendance, late arrivals and departures, selected repeaters, atomic lane swaps, saved heat lock, Photo Finish conditions, audit immutability, implement snapshots, ordered relay teams, session closure, RLS, unchanged official points. Rolled back.' as result;
